import itertools
import json
import random
import sys
from pathlib import Path

sys.path.append(str(Path('.').resolve()))
from problems import ThreeColoring, ThreeSat
from reduce import reduce


def three_coloring_bruteforce(instance):
    n = instance['n']
    edges = instance['edges']
    # assign colors 0,1,2
    for colors in itertools.product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if colors[u] == colors[v]:
                ok = False
                break
        if ok:
            return True
    # edge cases: n=0 always yes, but loop covers it (empty product gives one tuple)
    return False


def three_sat_bruteforce(instance):
    m = instance['num_vars']
    clauses = instance['clauses']
    for assignment in itertools.product([False, True], repeat=m):
        # assignment is tuple indexed 0..m-1 for var 1..m
        ok = True
        for clause in clauses:
            clause_sat = False
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var]
                if lit > 0 and val:
                    clause_sat = True
                    break
                if lit < 0 and not val:
                    clause_sat = True
                    break
            if not clause_sat:
                ok = False
                break
        if ok:
            return True
    return False


def random_graph(max_n=5):
    n = random.randint(0, max_n)
    possible_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    edges = []
    for (i, j) in possible_edges:
        if random.choice([True, False]):
            edges.append([i, j])
    return {"n": n, "edges": edges}


def run_tests(num_trials=200):
    passed = 0
    for _ in range(num_trials):
        inst = random_graph()
        # validate source
        ThreeColoring.validate(inst)
        src_ans = three_coloring_bruteforce(inst)
        red = reduce(inst)
        ThreeSat.validate(red)
        tgt_ans = three_sat_bruteforce(red)
        if src_ans == tgt_ans:
            passed += 1
        else:
            print("Mismatch!", inst, src_ans, red, tgt_ans)
            break
    return passed, num_trials

if __name__ == '__main__':
    passed, total = run_tests(200)
    verdict = {
        "verified": passed == total,
        "tests_run": total,
        "tests_passed": passed,
    }
    print(json.dumps(verdict, indent=2))
    Path('verdict.json').write_text(json.dumps(verdict))
EOF"}

